  CAST(BX'B6E6DFFF79B350B89B9B13F7229697BE' AS UUID), CAST(BX'F8EE2413514645658C892DD0EA75BCC7' AS UUID), 'Correct results can hide a terrible plan',
  'Query returns correct rows but is painfully slow; nobody flagged it because it "worked."', 'Stale statistics (off filter factor) or a missing index driving a table space scan / poor access path.', 'Examine the plan; refresh RUNSTATS / statistics; add or adjust the missing index when the access path confirms it.',
